Definition nest_host_f (sc : Z) : bool :=
  let size := UNIT * size_class sc in
  forallb (fun cnt0 => let cnt1 := bump size cnt0 in
     (PGSZ / 2 <? size * cnt1 + UNIT)
     || (let j := size_to_class (UNIT + cnt1 * size - IB) in (j =? 15) || (j =? 19) || (j =? 23))) (cnt0_list sc).
